{
  description = "cachet: a self-hostable nix binary cache on Cloudflare Workers";

  # why: plain github: refs keep the flake registry out of the dependency
  # path. The channel is nixos-unstable because only dev and build tools come
  # from it; the compiler comes from rust-toolchain.toml through rust-overlay.
  # flake.lock pins every revision, and dependabot proposes updates.
  # why: no nixConfig block. extra-substituters is a restricted client
  # setting that a non-trusted user ignores, so cache trust is wired in CI,
  # not committed here.
  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";

    flake-parts.url = "github:hercules-ci/flake-parts";
    flake-parts.inputs.nixpkgs-lib.follows = "nixpkgs";

    treefmt-nix.url = "github:numtide/treefmt-nix";
    treefmt-nix.inputs.nixpkgs.follows = "nixpkgs";

    # why: crane builds the workspace as a proper derivation, compiling the
    # dependency closure once and substituting it into every check.
    crane.url = "github:ipetkov/crane";

    # why: rust-overlay resolves the exact toolchain pinned in
    # rust-toolchain.toml, the single source of truth for the compiler.
    rust-overlay.url = "github:oxalica/rust-overlay";
    rust-overlay.inputs.nixpkgs.follows = "nixpkgs";
  };

  outputs =
    inputs@{ flake-parts, ... }:
    flake-parts.lib.mkFlake { inherit inputs; } {
      # The two CI and dev-machine architectures in both operating systems.
      # The production target (wasm32-unknown-unknown) is a Rust target, not
      # a nix system.
      systems = [
        "x86_64-linux"
        "aarch64-linux"
        "x86_64-darwin"
        "aarch64-darwin"
      ];

      imports = [
        inputs.treefmt-nix.flakeModule
        ./nix/rust-workspace.nix
        ./nix/treefmt.nix
        ./nix/devshell.nix
        ./nix/checks.nix
        ./nix/entire.nix
      ];
    };
}

1	// The deploy-time configuration contract. Every value the stack needs is
2	// read from the environment exactly once, here, and every missing value is
3	// named in one refusal: a deploy that cannot configure itself fails before
4	// touching the account, never after half-provisioning it.
5	
6	/** Everything a stage deploys with. */
7	export interface StageConfig {
8	  /** The deployment's name as invoked: the alchemy stage and the
9	   *  resource names (`cachet-<name>`, or the name as-is when it
10	   *  already starts with the prefix). */
11	  stage: string;
12	  /** The deployment's host name: the signing-key name prefix and, in
13	   *  production, the custom domain. */
14	  host: string;
15	  /** Comma-joined GitHub org slugs the deployment serves. */
16	  orgs: string;
17	  /** Comma-joined GitHub logins with admin rights. */
18	  admins: string;
19	  /** The GitHub OAuth App's client id. */
20	  oauthClientId: string;
21	  /** The OIDC audience (default `cachet`). */
22	  audience: string;
23	  /** The ref permitted to renew leases. */
24	  defaultBranchRef: string;
25	  /** The custom domain to attach; defaults to the host. */
26	  domain: string;
27	  /** The browser OAuth flow's redirect target, when a UI exists. */
28	  uiOrigin: string | undefined;
29	  /** The GC grace override; the worker's default (14 days) applies unset. */
30	  gcGraceMs: string | undefined;
31	  // The Cloudflare API token the counter route reads analytics with,
32	  // scoped to reading them and nothing else. Absent means the deployment
33	  // counts but does not report.
34	  statsToken: string | undefined;
35	}
36	
37	const REQUIRED = ["HOST", "ORGS", "OAUTH_CLIENT_ID", "ADMINS"] as const;
38	/** The worker's secrets, read by the stack through Config.redacted. */
39	const SECRETS = ["CACHET_SIGNING_KEY", "CACHET_OAUTH_CLIENT_SECRET"] as const;
40	
41	/** One environment variable under the deploy prefix, empty reads as absent. */
42	function value(name: string): string | undefined {
43	  const found = process.env[`CACHET_DEPLOY_${name}`]?.trim();
44	  return found === "" || found === undefined ? undefined : found;
45	}
46	
47	/** Normalize a comma list: trim every entry, drop empties, re-join. */
48	function commaList(raw: string): string {
49	  const items = raw
50	    .split(",")
51	    .map((item) => item.trim())
52	    .filter((item) => item !== "");
53	  return items.join(",");
54	}
55	
56	/**
57	 * Resolve the stage's configuration from `CACHET_DEPLOY_*` variables and the
58	 * two deploy-time secrets. Throws naming every missing variable at once: the
59	 * operator fixes the set, not a drip-feed of one failure per run.
60	 */
61	export function loadStageConfig(stage: string): StageConfig {
62	  if (!/^[a-z][a-z0-9-]{1,31}$/.test(stage)) {
63	    // why: the name becomes the R2 bucket, KV namespace, and worker name
64	    // (prefixed with cachet- when absent), so it must fit the strictest
65	    // of those grammars (bucket names).
66	    throw new Error(
67	      `deployment name "${stage}" must match ^[a-z][a-z0-9-]{1,31}$`,
68	    );
69	  }
70	  const missing = REQUIRED.filter((name) => value(name) === undefined).map(
71	    (name) => `CACHET_DEPLOY_${name}`,
72	  );
73	  for (const secret of SECRETS) {
74	    if ((process.env[secret]?.trim() ?? "") === "") {
75	      missing.push(secret);
76	    }
77	  }
78	  if (missing.length > 0) {
79	    throw new Error(
80	      `the ${stage} deployment is missing: ${missing.join(", ")}. ` +
81	        `Set them in infra/.env.${stage} or in the CI environment's variables and secrets (docs/DEPLOY.md).`,
82	    );
83	  }
84	
85	  const host = value("HOST") as string;
86	  if (!/^[a-z0-9][a-z0-9.-]*[a-z0-9]$/.test(host) || host.includes("..")) {
87	    throw new Error(
88	      `CACHET_DEPLOY_HOST=${JSON.stringify(host)} is not a plausible hostname`,
89	    );
90	  }
91	
92	  // why: workers.dev and preview URLs are disabled on every stage, so the
93	  // worker needs a custom domain; the host is the natural one because it
94	  // already names the deployment and the signing key.
95	  const domain = value("DOMAIN") ?? host;
96	  return {
97	    stage,
98	    host,
99	    orgs: commaList(value("ORGS") as string),
100	    admins: commaList(value("ADMINS") as string),
101	    oauthClientId: value("OAUTH_CLIENT_ID") as string,
102	    audience: value("AUDIENCE") ?? "cachet",
103	    defaultBranchRef: value("DEFAULT_BRANCH_REF") ?? "refs/heads/main",
104	    domain,
105	    uiOrigin: value("UI_ORIGIN"),
106	    gcGraceMs: value("GC_GRACE_MS"),
107	    statsToken: value("STATS_TOKEN"),
108	  };
109	}
