struct OAuthConfig {
    web_base: String,
    client_id: String,
    client_secret: String,
    redirect_uri: String,
    ui_origin: Option<String>,
}

fn oauth_config(env: &Env) -> cachet_core::error::Result<OAuthConfig> {
    // why: the var only ever overrides (lanes, GitHub Enterprise hosts);
    // github.com is the default and needs no config.
    let web_base = cachet_core::constants::override_or(
        env.var("CACHET_GITHUB_WEB_URL")
            .ok()
            .map(|value| value.to_string())
            .as_deref(),
        cachet_core::constants::GITHUB_WEB_URL_DEFAULT,
    )
    .to_string();
    let client_id = env
        .var("CACHET_OAUTH_CLIENT_ID")
        .map_err(|_| ClientError::AuthUnavailable)?
        .to_string();
    let host = env
        .var("CACHET_HOST")
        .map_err(|_| ClientError::AuthUnavailable)?
        .to_string();
    let client_secret = env
        .secret(CLIENT_SECRET_BINDING)
        .map_err(|_| ClientError::AuthUnavailable)?
        .to_string();
    // The one optional piece: absent means the callback answers a bare 204
    // instead of redirecting to a UI.
    let ui_origin = env.var("CACHET_UI_ORIGIN").ok().map(|v| v.to_string());
    Ok(OAuthConfig {
        web_base,
        client_id,
        client_secret,
        redirect_uri: format!("https://{host}{}", oauth::CALLBACK_PATH),
        ui_origin,
    })
}

